#include "AppmenuServer.hpp"

#include "Ipc.hpp"
#include "Plugin.hpp"
#include "core/Appmenu.hpp"
#include "core/Protocol.hpp"

// Generated by hyprwayland-scanner from compositor/protocols/appmenu.xml (build-direct.sh writes it to
// compositor/build/protocols/). Includes <wayland-server.h>.
#include "protocols/appmenu.hpp"

#include <hyprland/src/Compositor.hpp>
#include <hyprland/src/desktop/state/WindowState.hpp>
#include <hyprland/src/desktop/view/Window.hpp>
#include <hyprland/src/event/EventBus.hpp>
#include <hyprland/src/protocols/core/Compositor.hpp>

#include <dlfcn.h>
#include <sys/types.h>

#include <cstdint>
#include <cstring>
#include <format>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace {
    namespace am = gf::appmenu;

    constexpr uint32_t kGlobalVersion = 2;

    // One org_kde_kwin_appmenu object.
    struct SObject {
        UP<COrgKdeKwinAppmenu> resource;
        WP<CWLSurfaceResource> surface;
        uint64_t               surfaceId = 0; // address of the surface, compared, never followed
        CHyprSignalListener    surfaceDestroyed;
        bool                   live   = true;  // false: inert (runtime unload), requests ignored
        bool                   warned = false; // one log line per object for rejected requests

        uint64_t               id() const {
            return reinterpret_cast<uintptr_t>(this);
        }
    };

    // One binding of the org_kde_kwin_appmenu_manager global.
    struct SManager {
        UP<COrgKdeKwinAppmenuManager> resource;
        bool                          live = true;
    };

    struct SObjects {
        std::vector<UP<SManager>> managers;
        std::vector<UP<SObject>>  objects;
    };

    struct SState {
        wl_global*                       global = nullptr;
        bool                             ready  = false;
        SObjects                         live;
        am::CRegistry                    registry;
        std::vector<CHyprSignalListener> listeners;
    };

    // Constructed on first use inside a guarded call (R13). Emptied by stop() before dlclose.
    SState& st() {
        static SState s;
        return s;
    }

    // Inert objects of clients still connected after a runtime unload (the library is pinned then). Deliberately
    // never destroyed: entries leave when libwayland destroys their resource, which can happen while Hyprland
    // exits, after static destructors would have run.
    SObjects& retired() {
        static auto* r = new SObjects;
        return *r;
    }

    uint64_t idOf(const void* p) {
        return reinterpret_cast<uintptr_t>(p);
    }

    std::string hexAddress(uint64_t address) {
        return std::format("{:x}", address);
    }

    void post(const am::Announcement& a) {
        if (!st().ready)
            return;
        gf::ipc::postEvent(gf::gfc::appmenuJson(hexAddress(a.window), a.registration.service, a.registration.path));
    }

    void post(const std::optional<am::Announcement>& a) {
        if (a)
            post(*a);
    }

    // Windows are looked up by comparing addresses; nothing the client sent is dereferenced.
    PHLWINDOW mappedWindowOf(const SP<CWLSurfaceResource>& surface) {
        if (!surface || !Desktop::windowState())
            return nullptr;
        for (const auto& w : Desktop::windowState()->windows()) {
            if (w && w->m_isMapped && w->resource() == surface)
                return w;
        }
        return nullptr;
    }

    PHLWINDOW mappedWindowByAddress(uint64_t address) {
        if (!Desktop::windowState())
            return nullptr;
        for (const auto& w : Desktop::windowState()->windows()) {
            if (w && w->m_isMapped && idOf(w.get()) == address)
                return w;
        }
        return nullptr;
    }

    template <typename T>
    void eraseFrom(std::vector<UP<T>>& v, const T* p) {
        std::erase_if(v, [p](const UP<T>& e) { return e.get() == p; });
    }

    pid_t clientPid(wl_client* client) {
        pid_t pid = 0;
        if (client)
            wl_client_get_credentials(client, &pid, nullptr, nullptr);
        return pid;
    }

    // Wayland strings are NUL-terminated (libwayland guarantees it for non-nullable "s" arguments); one byte past
    // the limit is enough to reject an over-long one.
    std::string_view boundedView(const char* s) {
        if (!s)
            return {};
        return {s, strnlen(s, am::kMaxNameLength + 1)};
    }

    // ---- org_kde_kwin_appmenu requests ------------------------------------------------------------------

    void objectGone(SObject* o) {
        if (o->live) {
            post(st().registry.objectGone(o->id()));
            eraseFrom(st().live.objects, o); // destroys o and its wl_resource (if still alive)
        } else
            eraseFrom(retired().objects, o);
    }

    void onSetAddress(SObject* o, const char* service, const char* path) {
        gf::guarded("appmenu set_address", [&] {
            if (!o->live)
                return;
            const auto s = boundedView(service);
            const auto p = boundedView(path);
            if (!am::isValidAddress(s, p)) {
                // Protocol-safe no-op: the request is ignored, the client is not disconnected.
                if (!o->warned)
                    gf::log(Log::WARN, "appmenu: ignored set_address with an invalid D-Bus name or object path (lengths {} and {}) on surface {:x}", s.size(), p.size(),
                            o->surfaceId);
                o->warned = true;
                return;
            }
            const auto surface = o->surface.lock();
            if (!surface)
                return; // the surface is gone: nothing to link
            const auto window = mappedWindowOf(surface);
            gf::log(Log::INFO, "appmenu: set_address service {} path {} on surface {:x} (window {})", s, p, o->surfaceId, window ? hexAddress(idOf(window.get())) : "not mapped");
            post(st().registry.setAddress(o->surfaceId, o->id(), am::Registration{.service = std::string{s}, .path = std::string{p}}, window ? idOf(window.get()) : 0));
        });
    }

    void onRelease(SObject* o) {
        gf::guarded("appmenu release", [&] { objectGone(o); });
    }

    void onObjectDestroyed(SObject* o) {
        gf::guarded("appmenu object destroyed", [&] { objectGone(o); });
    }

    void onSurfaceDestroyed(SObject* o) {
        gf::guarded("appmenu surface destroyed", [&] {
            if (!o->live)
                return;
            post(st().registry.surfaceGone(o->surfaceId));
            o->surface.reset();
        });
    }

    // ---- org_kde_kwin_appmenu_manager requests -------------------------------------------------------------

    void managerGone(SManager* m) {
        eraseFrom(m->live ? st().live.managers : retired().managers, m);
    }

    void onCreate(SManager* m, uint32_t id, wl_resource* surfaceResource) {
        gf::guarded("appmenu create", [&] {
            wl_client* client = m->resource->client();
            auto       o      = makeUnique<SObject>();
            o->resource       = makeUnique<COrgKdeKwinAppmenu>(client, m->resource->version(), id);
            if (!o->resource->resource()) {
                m->resource->noMemory();
                return;
            }
            o->live   = m->live && st().ready;
            auto* raw = o.get();
            raw->resource->setSetAddress([raw](COrgKdeKwinAppmenu* /*r*/, const char* service, const char* path) { onSetAddress(raw, service, path); });
            raw->resource->setRelease([raw](COrgKdeKwinAppmenu* /*r*/) { onRelease(raw); });
            raw->resource->setOnDestroy([raw](COrgKdeKwinAppmenu* /*r*/) { onObjectDestroyed(raw); });
            if (!raw->live) {
                retired().objects.push_back(std::move(o));
                return;
            }
            const auto surface = surfaceResource ? CWLSurfaceResource::fromResource(surfaceResource) : nullptr;
            raw->surface       = surface;
            raw->surfaceId     = idOf(surface.get());
            if (surface)
                raw->surfaceDestroyed = surface->m_events.destroy.listen([raw] { onSurfaceDestroyed(raw); });
            gf::log(Log::INFO, "appmenu: client pid {} created an appmenu object for surface {:x}", clientPid(client), raw->surfaceId);
            st().live.objects.push_back(std::move(o));
        });
    }

    void onManagerRelease(SManager* m) {
        gf::guarded("appmenu manager release", [&] { managerGone(m); });
    }

    void onManagerDestroyed(SManager* m) {
        gf::guarded("appmenu manager destroyed", [&] { managerGone(m); });
    }

    void bindManager(wl_client* client, void* /*data*/, uint32_t version, uint32_t id) {
        gf::guarded("appmenu bind", [&] {
            auto m      = makeUnique<SManager>();
            m->resource = makeUnique<COrgKdeKwinAppmenuManager>(client, version, id);
            if (!m->resource->resource()) {
                wl_client_post_no_memory(client);
                return;
            }
            m->live   = st().ready;
            auto* raw = m.get();
            raw->resource->setCreate([raw](COrgKdeKwinAppmenuManager* /*r*/, uint32_t newId, wl_resource* surface) { onCreate(raw, newId, surface); });
            raw->resource->setRelease([raw](COrgKdeKwinAppmenuManager* /*r*/) { onManagerRelease(raw); });
            raw->resource->setOnDestroy([raw](COrgKdeKwinAppmenuManager* /*r*/) { onManagerDestroyed(raw); });
            if (raw->live)
                gf::log(Log::INFO, "appmenu: client pid {} bound org_kde_kwin_appmenu_manager version {}", clientPid(client), version);
            (raw->live ? st().live.managers : retired().managers).push_back(std::move(m));
        });
    }

    // ---- windows ---------------------------------------------------------------------------------------

    void onWindowMapped(const PHLWINDOW& w) {
        if (!w || !w->m_isMapped)
            return;
        const auto surface = w->resource();
        if (surface)
            post(st().registry.windowMapped(idOf(surface.get()), idOf(w.get())));
    }

    void onWindowUnmapped(const PHLWINDOW& w) {
        if (w)
            post(st().registry.windowGone(idOf(w.get())));
    }

    // A destroyed window can no longer be named (its weak reference is expired): clear every registered window
    // that is not mapped any more. Normally the unmap (window.close) has done it already.
    void sweepWindows() {
        for (const auto window : st().registry.windows()) {
            if (!mappedWindowByAddress(window))
                post(st().registry.windowGone(window));
        }
    }

    void onWindowFocused(const PHLWINDOW& w) {
        if (w && w->m_isMapped)
            post(st().registry.query(idOf(w.get())));
    }

    // Keeps this library mapped after Hyprland's dlclose (live client objects point into it).
    bool pinLibrary() {
        Dl_info info{};
        if (dladdr(reinterpret_cast<const void*>(&bindManager), &info) == 0 || !info.dli_fname)
            return false;
        void* self = dlopen(info.dli_fname, RTLD_NOW | RTLD_NOLOAD | RTLD_NODELETE);
        if (!self)
            return false;
        dlclose(self); // drops this extra reference; the object stays marked NODELETE
        return true;
    }
} // namespace

namespace gf::appmenuServer {

    bool start() {
        auto& s = st();
        if (s.ready)
            return true;
        if (!g_pCompositor || !g_pCompositor->m_wlDisplay) {
            gf::log(Log::ERR, "appmenu: no Wayland display");
            return false;
        }
        auto& bus = Event::bus();
        if (!bus)
            return false;
        auto& ev = bus->m_events;
        auto& l  = s.listeners;
        l.push_back(ev.window.open.listen([](const PHLWINDOW& w) { gf::guarded("appmenu window.open", [&] { onWindowMapped(w); }); }));
        l.push_back(ev.window.close.listen([](const PHLWINDOW& w) { gf::guarded("appmenu window.close", [&] { onWindowUnmapped(w); }); }));
        l.push_back(ev.window.destroy.listen([](const PHLWINDOWREF& /*w*/) { gf::guarded("appmenu window.destroy", [] { sweepWindows(); }); }));
        l.push_back(ev.window.active.listen([](const PHLWINDOW& w, Desktop::eFocusReason /*reason*/) { gf::guarded("appmenu window.active", [&] { onWindowFocused(w); }); }));

        s.global = wl_global_create(g_pCompositor->m_wlDisplay, &org_kde_kwin_appmenu_manager_interface, kGlobalVersion, nullptr, bindManager);
        if (!s.global) {
            gf::log(Log::ERR, "appmenu: wl_global_create(org_kde_kwin_appmenu_manager) failed");
            s.listeners.clear();
            return false;
        }
        s.ready = true;
        gf::log(Log::INFO, "appmenu: org_kde_kwin_appmenu_manager version {} advertised", kGlobalVersion);
        return true;
    }

    void stop() {
        auto& s = st();
        s.listeners.clear();

        const bool   shuttingDown = !g_pCompositor || g_pCompositor->m_isShuttingDown;
        const size_t clientObjs   = s.live.managers.size() + s.live.objects.size();

        // At runtime the shell learns that the menus are gone; at shutdown nobody listens any more.
        const auto clears = s.registry.clear();
        if (!shuttingDown) {
            for (const auto& a : clears)
                post(a);
        }
        s.ready = false;

        if (!shuttingDown && clientObjs > 0 && pinLibrary()) {
            for (auto& m : s.live.managers) {
                m->live = false;
                retired().managers.push_back(std::move(m));
            }
            for (auto& o : s.live.objects) {
                o->live = false;
                o->surfaceDestroyed.reset();
                o->surface.reset();
                retired().objects.push_back(std::move(o));
            }
            s.live.managers.clear();
            s.live.objects.clear();
            if (s.global)
                wl_global_remove(s.global); // clients are told it is gone; libwayland frees it with the display
            s.global = nullptr;
            gf::log(Log::WARN, "appmenu: unloaded with {} client object(s) alive: they stay inert and this library stays in memory; a rebuilt plugin at the same path loads after Hyprland restarts",
                    clientObjs);
            return;
        }

        if (!shuttingDown && clientObjs > 0)
            gf::log(Log::ERR, "appmenu: could not pin the library: {} client object(s) destroyed; their clients get a protocol error at their next request on them", clientObjs);
        s.live.objects.clear();  // destructors destroy the wl_resources
        s.live.managers.clear();
        if (s.global) {
            wl_global_destroy(s.global);
            s.global = nullptr;
        }
        gf::log(Log::INFO, "appmenu: global and {} client object(s) destroyed{}", clientObjs, shuttingDown ? " (shutdown)" : "");
    }

    bool ready() {
        return st().ready;
    }

    bool announce(uint64_t windowAddress) {
        if (!st().ready || !mappedWindowByAddress(windowAddress))
            return false;
        post(st().registry.query(windowAddress));
        return true;
    }

} // namespace gf::appmenuServer
